import { useEffect, useMemo, useState } from "react";
import { useApp } from "../lib/store";
import { supabase, callFunction } from "../lib/supabase";
import { Card, Empty, LoadError, Modal, Spinner, useToast } from "../components/ui";

// Templates, and the two things that make them more than a notepad:
//
//  1. **Send.** Until now nothing in the product could send an email. The
//     send-campaign edge function existed, was correctly authenticated, and had
//     zero callers — so the merge tokens documented right here were substituted
//     by no code path anywhere. This screen is where that gets wired up.
//
//  2. **Follow-up steps.** An email template can be marked as step 1, 2 or 3 of
//     the automatic follow-up sequence. Previously that sequence was three
//     study-abroad emails compiled into the nurture function, signed AbroBot,
//     sent for whichever tenant cron happened to run. Now it is content each
//     business writes for itself — and a business that writes none sends none.

interface Template {
  id: string;
  org_id: string;
  name: string;
  channel: string;
  subject: string | null;
  body: string;
  nurture_step: number | null;
  nurture_segment: string | null;
  created_at: string;
}

// Tokens every record has, whatever the industry. The tenant's own custom
// fields are appended to these at render time — see `tokens` below. Hardcoding
// only this list meant a business whose useful details all live in custom
// fields (which, outside study-abroad, is most of them) had no way to merge
// them in, and no way to discover that {{custom.<key>}} even worked.
const BASE_TOKENS = [
  "{{first_name}}", "{{name}}", "{{email}}", "{{phone}}",
  "{{country}}", "{{course}}", "{{brand}}",
];

// Hours after the previous message, matching GAP_HOURS in the nurture function.
const STEP_TIMING = ["about an hour after the record is created", "3 days later", "4 days after that"];

const ALL_AUDIENCES = "";   // the empty string is "everyone", i.e. nurture_segment = null

export function Templates() {
  const { org, ui, isAdmin, stages, fields } = useApp();
  const [rows, setRows] = useState<Template[]>([]);
  const [loading, setLoading] = useState(true);
  // Held in state, not just toasted. A toast is gone in 3.2 seconds and leaves
  // "No templates yet" on screen — which an org with 40 templates reads as
  // "our templates are gone". The error has to outlive the toast.
  const [loadError, setLoadError] = useState<string | null>(null);
  const [editing, setEditing] = useState<Partial<Template> | null>(null);
  const [nurtureOn, setNurtureOn] = useState<boolean | null>(null);
  const [sending, setSending] = useState<Template | null>(null);
  // The audiences this org actually captures into, read from its own capture
  // keys. A hardcoded list would offer audiences that cannot exist here and
  // omit the ones that do — and an audience matching no record is a sequence
  // that silently never sends.
  const [segments, setSegments] = useState<string[]>([]);
  // The Save button had no busy guard, so a second click while the write was
  // still in flight inserted the template twice — two rows with the same name,
  // and on a sequence step the second one trips the unique index and reports a
  // "duplicate step" the user did not create. Same `saving` shape as AddLead in
  // Leads.tsx.
  const [saving, setSaving] = useState(false);
  const toast = useToast();

  const load = async () => {
    if (!org) { setLoading(false); return; }   // never leave the spinner up forever
    const [tpl, cfg, keys] = await Promise.all([
      supabase.from("message_templates").select("*").eq("org_id", org.id).order("created_at"),
      supabase.from("agent_config").select("nurture_enabled").eq("org_id", org.id).maybeSingle(),
      supabase.from("webhook_keys").select("segment").eq("org_id", org.id).eq("active", true),
    ]);
    // Failing to list audiences must not break the screen — it only narrows the
    // dropdown, and an existing template's own audience is added back below.
    setSegments([...new Set(((keys.data ?? []) as { segment: string | null }[])
      .map((k) => k.segment).filter((s): s is string => !!s))].sort());
    // An unread error here showed "No templates yet" AND reported automatic
    // follow-up as Off — two confident falsehoods from one failed request.
    if (tpl.error) { setLoadError(tpl.error.message); toast.error(`Could not load templates: ${tpl.error.message}`); }
    else { setLoadError(null); setRows((tpl.data as Template[]) ?? []); }
    // null, not false, when we genuinely do not know — the card below
    // distinguishes "off" from "unknown" rather than asserting.
    setNurtureOn(cfg.error ? null : (cfg.data?.nurture_enabled ?? false));
    setLoading(false);
  };

  useEffect(() => { void load(); /* eslint-disable-next-line */ }, [org]);

  // The base tokens plus this org's own custom fields, so a business can merge
  // in the things it actually collects. The engine already resolves
  // {{custom.<key>}}; nothing had ever told anyone it existed.
  const tokens = useMemo(
    () => [...BASE_TOKENS, ...fields.map((f) => `{{custom.${f.key}}}`)],
    [fields],
  );

  // One entry per audience, because an org may now run several sequences at
  // once. The default sequence sorts first; named audiences follow.
  const sequences = useMemo(() => {
    const groups = new Map<string, Template[]>();
    rows.filter((r) => r.nurture_step !== null).forEach((r) => {
      const k = r.nurture_segment ?? ALL_AUDIENCES;
      groups.set(k, [...(groups.get(k) ?? []), r]);
    });
    return [...groups.entries()]
      .map(([audience, list]) => ({
        audience,
        list: list.sort((a, b) => a.nurture_step! - b.nurture_step!),
      }))
      .sort((a, b) => a.audience.localeCompare(b.audience));
  }, [rows]);

  const save = async () => {
    if (saving) return;
    if (!org || !editing) return;
    if (!editing.name?.trim() || !editing.body?.trim()) { toast.error("Name and message are required"); return; }

    // A WhatsApp template cannot be a step in an email sequence. Silently
    // storing one would produce a follow-up step the engine skips forever,
    // which looks like the sequence is running when it is not.
    const step = editing.channel === "whatsapp" ? null : (editing.nurture_step ?? null);

    // An audience only means something on a step. Storing one on a hand-sent
    // template would show a badge claiming this reaches a particular group when
    // nothing reads the column outside the sequence engine.
    const audience = step === null ? null : (editing.nurture_segment?.trim() || null);

    const payload = {
      org_id: org.id,
      name: editing.name.trim(),
      channel: editing.channel ?? "email",
      subject: editing.subject?.trim() || null,
      body: editing.body,
      nurture_step: step,
      nurture_segment: audience,
    };
    // `.select("id")` on the update so a refusal is distinguishable from
    // success. PostgREST answers an UPDATE whose WHERE matches no VISIBLE row
    // with 204 and error: null — identical to a real save. A member whose
    // access was revoked keeps a working token for up to an hour, and for that
    // hour every template edit said "Template saved" and changed nothing.
    setSaving(true);
    const { data, error } = editing.id
      ? await supabase.from("message_templates").update(payload).eq("id", editing.id).select("id")
      : await supabase.from("message_templates").insert(payload).select("id");
    setSaving(false);
    if (error) {
      // The unique index on the step is the likeliest failure, and "duplicate
      // key value violates..." tells a business owner nothing.
      //
      // Both index names are matched, because this screen has to stay honest
      // against a database that has not had 20260908120000 applied yet. On
      // such a database the live index is still ORG-WIDE, so the collision may
      // be with a template for a completely different audience — which is why
      // the message deliberately does not name one. Asserting "step 1 for
      // crm-website already exists" would send someone hunting for a template
      // that isn't there.
      const collided = /message_templates_org_(nurture|segment)_step/.test(error.message)
        || /duplicate key/i.test(error.message);
      toast.error(
        collided
          ? `Another email template is already step ${(step ?? 0) + 1}. ` +
            `Two templates cannot share a step for the same audience — change one of them first.`
          : error.message,
      );
      return;
    }
    if (!data?.length) {
      await load();
      toast.error(
        editing.id
          ? "Nothing was saved — the template is no longer there, or you no longer have permission to change it."
          : "Nothing was saved — you no longer have permission to add templates here.",
      );
      return;
    }
    setEditing(null);
    await load();
    toast.show("Template saved");
  };

  const remove = async (id: string) => {
    if (!confirm("Delete this template? This cannot be undone.")) return;
    // Same reason as `save`: a DELETE matching no visible row is a 204 with
    // error: null, so "Deleted" was printed over a template the reload then put
    // straight back in the list.
    const { data, error } = await supabase.from("message_templates").delete().eq("id", id).select("id");
    if (error) { toast.error(error.message); return; }
    if (!data?.length) {
      await load();
      toast.error("Nothing was deleted — the template is already gone, or you no longer have permission to delete it.");
      return;
    }
    await load();
    toast.show("Deleted");
  };

  if (loading) return <Spinner />;
  // Before anything below renders, because a failed templates read makes two
  // separate assertions false at once: the empty state says "No templates yet",
  // and the follow-up card says "no follow-up messages are written yet, so
  // nothing is being sent." Both read as facts about the org's data. Same
  // early-return shape as Archived and Leads.
  if (loadError) return <LoadError message={loadError} onRetry={() => void load()} />;

  return (
    <div className="stack">
      <div className="row">
        <div>
          <h1>Templates</h1>
          <p className="sub" style={{ marginTop: 2 }}>Reusable messages for email and WhatsApp</p>
        </div>
        <div className="spacer" />
        {isAdmin && (
          <button className="btn btn-primary" onClick={() => setEditing({ channel: "email", body: "" })}>
            + New template
          </button>
        )}
      </div>

      {/* The follow-up sequence, stated plainly, because "automatic email is
          switched on" and "automatic email will actually send" were different
          things and nothing on screen said so. */}
      <Card title={<h2>Automatic follow-up</h2>}>
        {nurtureOn === false ? (
          <p className="sub">
            Off. Nothing is emailed automatically. Turn it on in <b>Settings → AI Agent</b> once you
            have written the messages below.
          </p>
        ) : nurtureOn === null ? (
          // `null` means the agent_config read failed, and load() sets it
          // deliberately so this screen can distinguish "off" from "unknown".
          // It then fell straight through into copy asserting the sequence was
          // switched on — producing exactly the confident falsehood the null
          // was introduced to avoid.
          <p className="sub">
            We couldn't read whether automatic follow-up is switched on, so this
            card can't tell you either way. Reload, or check{" "}
            <b>Settings → AI Agent</b>. The templates below are unaffected.
          </p>
        ) : sequences.length === 0 ? (
          <p className="sub">
            Switched on, but <b>no follow-up messages are written yet, so nothing is being sent.</b>{" "}
            Mark an email template as step 1 to start the sequence.
          </p>
        ) : (
          <>
            <p className="sub" style={{ marginBottom: 10 }}>
              Sent automatically to any {ui.leadNoun.toLowerCase()} with an email address who has not
              reached a won or lost stage, until they reply or unsubscribe.
            </p>
            {sequences.map(({ audience, list }) => (
              <div key={audience || "default"} style={{ marginBottom: 12 }}>
                <div className="row-wrap" style={{ gap: 6, marginBottom: 4 }}>
                  <span className={audience ? "pill" : "pill pill-muted"}>
                    {audience ? `🎯 ${audience}` : "Everyone else"}
                  </span>
                  <span className="sub" style={{ fontSize: 12 }}>
                    {list.length} message{list.length > 1 ? "s" : ""}
                  </span>
                </div>
                <ol className="sub" style={{ margin: 0, paddingLeft: 20 }}>
                  {list.map((t) => (
                    <li key={t.id} style={{ marginBottom: 3 }}>
                      <b>{t.name}</b> — {STEP_TIMING[t.nurture_step!] ?? "later"}
                    </li>
                  ))}
                </ol>
              </div>
            ))}
            {/* The failure mode segmentation introduces, said out loud. A
                business that writes copy only for one source stops following up
                with everybody else, and nothing on screen would otherwise say
                so — it just looks like a working sequence. */}
            {!sequences.some((s) => s.audience === ALL_AUDIENCES) && (
              <p className="sub" style={{ fontSize: 12, marginTop: 4 }}>
                Every sequence above is for a specific source.{" "}
                <b>
                  {ui.leadNoun}s from any other source receive no automatic follow-up at all.
                </b>{" "}
                Add a step with the audience set to <i>Everyone</i> if you want a fallback.
              </p>
            )}
          </>
        )}
      </Card>

      {rows.length === 0 ? (
        <Card>
          <Empty
            icon="📄"
            title="No templates yet"
            hint={`Write the messages your team sends most — first response, follow-up, ${ui.leadNoun.toLowerCase()} re-engagement.`}
          />
        </Card>
      ) : (
        <div className="grid grid-2">
          {rows.map((t) => (
            <Card
              key={t.id}
              title={
                <div>
                  <h2>{t.name}</h2>
                  <div className="row-wrap" style={{ marginTop: 4, gap: 5 }}>
                    <span className="pill pill-muted">
                      {t.channel === "whatsapp" ? "💬 WhatsApp" : "✉️ Email"}
                    </span>
                    {t.nurture_step !== null && (
                      <span className="pill">🔁 Follow-up step {t.nurture_step + 1}</span>
                    )}
                    {t.nurture_step !== null && t.nurture_segment && (
                      <span className="pill pill-muted">🎯 {t.nurture_segment}</span>
                    )}
                  </div>
                </div>
              }
              action={
                isAdmin && (
                  <div className="row">
                    {t.channel !== "whatsapp" && (
                      <button className="btn btn-sm" onClick={() => setSending(t)}>✉️ Send</button>
                    )}
                    <button className="btn btn-sm" onClick={() => setEditing(t)}>Edit</button>
                    <button className="btn btn-sm btn-danger" onClick={() => void remove(t.id)}>🗑</button>
                  </div>
                )
              }
            >
              {t.subject && <div style={{ fontWeight: 600, marginBottom: 6 }}>{t.subject}</div>}
              <div className="sub" style={{ whiteSpace: "pre-wrap", maxHeight: 150, overflow: "hidden" }}>{t.body}</div>
            </Card>
          ))}
        </div>
      )}

      {sending && <SendModal template={sending} stages={stages} onClose={() => setSending(null)} toast={toast} />}

      {editing && (
        <Modal title={editing.id ? "Edit template" : "New template"} onClose={() => setEditing(null)} wide>
          <div className="field">
            <label className="label">Name</label>
            <input
              className="input"
              value={editing.name ?? ""}
              onChange={(e) => setEditing({ ...editing, name: e.target.value })}
              placeholder="First response"
              autoFocus
            />
          </div>
          <div className="field">
            <label className="label">Channel</label>
            <select
              className="select"
              value={editing.channel ?? "email"}
              onChange={(e) => setEditing({ ...editing, channel: e.target.value })}
            >
              <option value="email">Email</option>
              <option value="whatsapp">WhatsApp</option>
            </select>
          </div>
          {editing.channel !== "whatsapp" && (
            <>
              <div className="field">
                <label className="label">Subject</label>
                <input
                  className="input"
                  value={editing.subject ?? ""}
                  onChange={(e) => setEditing({ ...editing, subject: e.target.value })}
                />
              </div>
              <div className="field">
                <label className="label">Use in automatic follow-up</label>
                <select
                  className="select"
                  value={editing.nurture_step === null || editing.nurture_step === undefined ? "" : String(editing.nurture_step)}
                  onChange={(e) =>
                    setEditing({ ...editing, nurture_step: e.target.value === "" ? null : Number(e.target.value) })}
                >
                  <option value="">No — I send this by hand</option>
                  <option value="0">Step 1 — {STEP_TIMING[0]}</option>
                  <option value="1">Step 2 — {STEP_TIMING[1]}</option>
                  <option value="2">Step 3 — {STEP_TIMING[2]}</option>
                </select>
                <p className="sub" style={{ fontSize: 12, marginTop: 5 }}>
                  Steps are sent automatically, in order, and stop as soon as someone reaches a won or
                  lost stage or unsubscribes.
                </p>
              </div>

              {/* Audience. Only meaningful on a step, so it is hidden otherwise
                  rather than shown disabled — a control that does nothing is
                  worse than one that isn't there. */}
              {editing.nurture_step !== null && editing.nurture_step !== undefined && (
                <div className="field">
                  <label className="label">Who this sequence is for</label>
                  <select
                    className="select"
                    value={editing.nurture_segment ?? ALL_AUDIENCES}
                    onChange={(e) =>
                      setEditing({ ...editing, nurture_segment: e.target.value || null })}
                  >
                    <option value={ALL_AUDIENCES}>
                      Everyone — anyone without a sequence of their own
                    </option>
                    {/* The org's own capture segments, plus this template's
                        current one even if its key was since deleted, so
                        editing an old template cannot silently reassign it. */}
                    {[...new Set([
                      ...segments,
                      ...(editing.nurture_segment ? [editing.nurture_segment] : []),
                    ])].sort().map((s) => (
                      <option key={s} value={s}>Only {ui.leadNoun.toLowerCase()}s from “{s}”</option>
                    ))}
                  </select>
                  <p className="sub" style={{ fontSize: 12, marginTop: 5 }}>
                    {segments.length === 0 ? (
                      <>
                        You have no audiences yet, so this sequence goes to everyone. To split it,
                        give a capture key an audience name in <b>Integrations</b> — records captured
                        on that key can then have follow-up written just for them.
                      </>
                    ) : (
                      <>
                        Audiences come from your capture keys in <b>Integrations</b>. Give a form or
                        channel its own key and you can write follow-up that speaks to what those
                        people actually asked about. An audience with its own sequence does not also
                        receive the “Everyone” one. Records added by hand or imported have no
                        audience, so they get “Everyone”.
                      </>
                    )}
                  </p>
                </div>
              )}
            </>
          )}
          <div className="field">
            <label className="label">Message</label>
            <textarea
              className="textarea"
              style={{ minHeight: 170 }}
              value={editing.body ?? ""}
              onChange={(e) => setEditing({ ...editing, body: e.target.value })}
            />
            <div className="row-wrap" style={{ marginTop: 7 }}>
              {tokens.map((tk) => (
                <button
                  key={tk}
                  type="button"
                  className="pill pill-muted"
                  style={{ border: "none", cursor: "pointer" }}
                  onClick={() => setEditing({ ...editing, body: (editing.body ?? "") + tk })}
                >
                  {tk}
                </button>
              ))}
            </div>
            <p className="sub" style={{ fontSize: 12, marginTop: 5 }}>
              Click a token to insert it. It's replaced with the record's details when the message is
              sent. A token we don't recognise is left as-is rather than blanked, so a typo is visible
              rather than silently deleting half a sentence.
            </p>
          </div>
          <div className="row" style={{ justifyContent: "flex-end" }}>
            <button className="btn" onClick={() => setEditing(null)} disabled={saving}>Cancel</button>
            <button className="btn btn-primary" onClick={save} disabled={saving}>
              {saving ? "Saving…" : "Save"}
            </button>
          </div>
        </Modal>
      )}
      {toast.node}
    </div>
  );
}

// ── Send ────────────────────────────────────────────────────────────────────
// Two-step by design. Sending a few hundred emails is not undoable, and the
// one number that matters — how many people this reaches — is the number the
// composer never showed. So: pick an audience, see the count, then send.
function SendModal({
  template, stages, onClose, toast,
}: {
  template: Template;
  stages: { key: string; label: string }[];
  onClose: () => void;
  toast: ReturnType<typeof useToast>;
}) {
  const [stageKey, setStageKey] = useState("");
  const [onlyMine, setOnlyMine] = useState(false);
  const [count, setCount] = useState<number | null>(null);
  const [remaining, setRemaining] = useState<number | null>(null);
  const [busy, setBusy] = useState(false);
  const [testTo, setTestTo] = useState("");

  const audience = () => ({ stage_key: stageKey || undefined, onlyMine: onlyMine || undefined });

  // Any change to the audience invalidates a count the person may be looking
  // at. Sending against a stale count is how "it went to 12 people" becomes
  // "it went to 1,200".
  const changeStage = (v: string) => { setStageKey(v); setCount(null); };
  const changeMine = (v: boolean) => { setOnlyMine(v); setCount(null); };

  const check = async () => {
    setBusy(true);
    try {
      const r = await callFunction<{ matched: number; capped: boolean; remaining: number | null }>(
        "send-campaign", {
          subject: template.subject || template.name,
          body: template.body,
          audience: audience(),
          count_only: true,
        });
      setCount(r.matched);
      setRemaining(r.remaining);
      if (r.capped) toast.error("More than 2,000 match — only the first 2,000 would be sent.");
    } catch (e) { toast.error((e as Error).message); }
    finally { setBusy(false); }
  };

  const sendTest = async () => {
    if (!testTo.trim()) { toast.error("Enter an address for the test"); return; }
    setBusy(true);
    try {
      await callFunction("send-campaign", {
        subject: template.subject || template.name,
        body: template.body,
        test_to: testTo.trim(),
      });
      toast.show(`Test sent to ${testTo.trim()}`);
    } catch (e) { toast.error((e as Error).message); }
    finally { setBusy(false); }
  };

  const sendAll = async () => {
    setBusy(true);
    try {
      const r = await callFunction<{ sent: number; matched: number; errors: string[] }>("send-campaign", {
        subject: template.subject || template.name,
        body: template.body,
        audience: audience(),
      });
      // Partial failure is the normal case with email — a few bounced
      // addresses in a batch of hundreds. Reporting only the successes would
      // hide it.
      if (r.errors?.length) {
        toast.error(`Sent ${r.sent} of ${r.matched}. ${r.errors.length} failed — first: ${r.errors[0]}`);
      } else {
        toast.show(`Sent to ${r.sent} ${r.sent === 1 ? "person" : "people"}`);
      }
      onClose();
    } catch (e) { toast.error((e as Error).message); }
    finally { setBusy(false); }
  };

  return (
    <Modal title={`Send "${template.name}"`} onClose={onClose} wide>
      {!template.subject && (
        <p className="sub" style={{ marginBottom: 10 }}>
          This template has no subject line, so the template name will be used as the subject.
        </p>
      )}

      <div className="field">
        <label className="label">Who should receive it?</label>
        <select className="select" value={stageKey} onChange={(e) => changeStage(e.target.value)}>
          <option value="">Everyone with an email address</option>
          {stages.map((s) => <option key={s.key} value={s.key}>Only: {s.label}</option>)}
        </select>
        <label className="row" style={{ marginTop: 8, gap: 8, cursor: "pointer" }}>
          <input type="checkbox" checked={onlyMine} onChange={(e) => changeMine(e.target.checked)} />
          <span className="sub">Only the ones assigned to me</span>
        </label>
        <p className="sub" style={{ fontSize: 12, marginTop: 6 }}>
          Anyone who has unsubscribed is always excluded.
        </p>
      </div>

      <div className="field">
        <label className="label">Send a test to yourself first</label>
        <div className="row">
          <input
            className="input"
            placeholder="you@example.com"
            value={testTo}
            onChange={(e) => setTestTo(e.target.value)}
          />
          <button className="btn" disabled={busy} onClick={() => void sendTest()}>Send test</button>
        </div>
      </div>

      <hr style={{ border: "none", borderTop: "1px solid var(--border)", margin: "16px 0" }} />

      {count === null ? (
        <div className="row" style={{ justifyContent: "flex-end" }}>
          <button className="btn" onClick={onClose}>Cancel</button>
          <button className="btn btn-primary" disabled={busy} onClick={() => void check()}>
            {busy ? "Checking…" : "Check how many"}
          </button>
        </div>
      ) : count === 0 ? (
        <div className="row" style={{ justifyContent: "space-between" }}>
          <p className="sub">No one matches that audience.</p>
          <button className="btn" onClick={onClose}>Close</button>
        </div>
      ) : (
        <div className="row" style={{ justifyContent: "space-between" }}>
          <div>
            <p className="sub">
              This will email <b>{count}</b> {count === 1 ? "person" : "people"}. It cannot be undone.
            </p>
            {remaining !== null && (
              <p className="sub" style={{ fontSize: 12, marginTop: 3 }}>
                {remaining < count
                  // Said before the button is pressed, not after a partial send:
                  // stopping halfway leaves no way to tell who received it.
                  ? <>Only <b>{remaining}</b> left in this month's allowance — narrow the audience or upgrade.</>
                  : <>{remaining} of this month's email allowance remaining.</>}
              </p>
            )}
          </div>
          <div className="row">
            <button className="btn" onClick={onClose}>Cancel</button>
            <button
              className="btn btn-primary"
              disabled={busy || (remaining !== null && remaining < count)}
              onClick={() => void sendAll()}
            >
              {busy ? "Sending…" : `Send to ${count}`}
            </button>
          </div>
        </div>
      )}
    </Modal>
  );
}
