import { useMemo, useState } from "react";
import { useApp, useFollowUpCount, useLeads } from "../lib/store";
import { supabase } from "../lib/supabase";
import { Card, Empty, ScoreChip, Spinner, StagePill, useToast, LoadError, TruncationNotice } from "../components/ui";
import type { Lead } from "../lib/types";

// Follow-up calendar. A month grid plus the selected day's list, because the
// question people actually ask is "who am I calling today".

const DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

/**
 * Local calendar day, NOT the UTC day.
 *
 * This was `d.toISOString().slice(0,10)`, which is a UTC date string — and the
 * grid cells are built from LOCAL midnights. In IST (UTC+5:30) those disagree
 * by a day for the first 5h30m of every date: `new Date(2026, 8, 15)` is
 * 2026-09-14T18:30Z, so the cell displaying "15" was keyed "2026-09-14".
 *
 * Net effect for an Indian user — which is every user — **every follow-up
 * appeared one day late**, "today" highlighted tomorrow's box, and the day
 * list actually spanned 05:30 today to 05:29 tomorrow, dropping anything due
 * early in the morning and stealing anything due after midnight.
 *
 * On the screen whose entire job is "who am I calling today".
 */
const iso = (d: Date) =>
  `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;

// Parse a "YYYY-MM-DD" key back to a LOCAL midnight. `new Date("2026-09-02")`
// parses as UTC midnight, which renders as the previous evening in IST — the
// same off-by-one arriving through the back door.
const fromIso = (s: string) => {
  const [y, m, d] = s.split("-").map(Number);
  return new Date(y, (m ?? 1) - 1, d ?? 1);
};

export function Calendar({ navigate }: { navigate: (to: string) => void }) {
  const { org, ui, stages } = useApp();
  const { leads, loading, error, reload, totalLeads, truncated } = useLeads(org?.id);
  const [cursor, setCursor] = useState(() => new Date());
  const [selected, setSelected] = useState(() => iso(new Date()));
  const toast = useToast();

  const doneKeys = useMemo(
    () => stages.filter((s) => s.is_won || s.is_lost).map((s) => s.key),
    [stages],
  );

  const openLeads = useMemo(() => {
    const done = new Set(doneKeys);
    return leads.filter((l) => !done.has(l.stage_key ?? l.stage) && l.next_follow_up_at);
  }, [leads, doneKeys]);

  // The true number of open records carrying a follow-up date, counted on the
  // server. The header said "N scheduled follow-ups" from the loaded page —
  // on the one screen whose entire job is proving nobody has been missed,
  // which is precisely where an undercount is most expensive.
  const trueFollowUps = useFollowUpCount(org?.id, doneKeys, truncated);

  const byDay = useMemo(() => {
    const m: Record<string, Lead[]> = {};
    openLeads.forEach((l) => {
      // A malformed date makes toISOString throw RangeError — which, inside a
      // useMemo with no error boundary, used to take the whole app down.
      // next_follow_up_at is written by the CSV importer, the lead webhook and
      // automations, none of which validate it here.
      const t = new Date(l.next_follow_up_at!);
      if (Number.isNaN(t.getTime())) return;
      const k = iso(t);
      (m[k] ??= []).push(l);
    });
    return m;
  }, [openLeads]);

  // Month grid starting Monday
  const cells = useMemo(() => {
    const first = new Date(cursor.getFullYear(), cursor.getMonth(), 1);
    const start = new Date(first);
    const dow = (first.getDay() + 6) % 7; // Mon = 0
    start.setDate(first.getDate() - dow);
    return Array.from({ length: 42 }, (_, i) => {
      const d = new Date(start);
      d.setDate(start.getDate() + i);
      return d;
    });
  }, [cursor]);

  const reschedule = async (lead: Lead, days: number) => {
    const next = new Date();
    next.setDate(next.getDate() + days);
    // `.select("id")` so a refusal is distinguishable from success. PostgREST
    // answers an UPDATE whose WHERE matches no VISIBLE row with 204 and
    // error: null — identical to a real save. A member whose access was revoked
    // keeps a usable token for up to an hour, and in that hour every reschedule
    // named a date, moved nothing, and left the follow-up sitting on its old day.
    const { data, error } = await supabase
      .from("leads")
      .update({ next_follow_up_at: next.toISOString() })
      .eq("id", lead.id)
      .select("id");
    if (error) { toast.error(error.message); return; }
    if (!data?.length) {
      await reload();
      toast.error(`${lead.name} was not moved — the record is no longer visible to you, or you no longer have permission to change it.`);
      return;
    }
    await reload();
    toast.show(`${lead.name} moved to ${next.toLocaleDateString("en-IN", { day: "numeric", month: "short" })}`);
  };

  if (loading) return <Spinner />;


  // An unread error here told the customer they have no records. store.tsx

  // documents that exact failure — "a customer with 4,000 records being told,

  // convincingly, that they have none" — and this screen ignored it anyway.

  if (error) return <LoadError message={error} onRetry={reload} />;

  const today = iso(new Date());
  const dayList = byDay[selected] ?? [];

  return (
    <div className="stack">
      {/* This screen showed no truncation notice at all — the month grid simply
          omitted every follow-up belonging to an older record, silently. */}
      <TruncationNotice
        loaded={leads.length}
        total={totalLeads}
        noun={ui.leadNounPlural.toLowerCase()}
        what="Follow-ups on older records are not plotted on the grid below."
      />

      <div className="row">
        <div>
          <h1>Calendar</h1>
          <p className="sub" style={{ marginTop: 2 }}>
            {(trueFollowUps ?? openLeads.length).toLocaleString("en-IN")} scheduled follow-ups
            {trueFollowUps !== null && trueFollowUps > openLeads.length
              ? ` · ${openLeads.length.toLocaleString("en-IN")} of them plotted below`
              : ""}
          </p>
        </div>
        <div className="spacer" />
        <div className="row">
          <button className="btn btn-sm" onClick={() => setCursor(new Date(cursor.getFullYear(), cursor.getMonth() - 1, 1))}>←</button>
          <b style={{ minWidth: 150, textAlign: "center" }}>
            {cursor.toLocaleDateString("en-IN", { month: "long", year: "numeric" })}
          </b>
          <button className="btn btn-sm" onClick={() => setCursor(new Date(cursor.getFullYear(), cursor.getMonth() + 1, 1))}>→</button>
          <button className="btn btn-sm" onClick={() => { setCursor(new Date()); setSelected(today); }}>Today</button>
        </div>
      </div>

      <Card>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", gap: 5 }}>
          {DAYS.map((d) => (
            <div key={d} className="sub" style={{ textAlign: "center", fontSize: 11, fontWeight: 700, padding: "3px 0" }}>{d}</div>
          ))}
          {cells.map((d) => {
            const k = iso(d);
            const items = byDay[k] ?? [];
            const otherMonth = d.getMonth() !== cursor.getMonth();
            const isToday = k === today;
            const isSel = k === selected;
            const overdue = k < today && items.length > 0;
            return (
              <button
                key={k}
                onClick={() => setSelected(k)}
                style={{
                  minHeight: 62, borderRadius: 10, padding: 6, textAlign: "left", cursor: "pointer",
                  border: isSel ? "2px solid var(--industry)" : "1px solid var(--border)",
                  background: isToday ? "var(--industry-soft)" : "var(--card)",
                  opacity: otherMonth ? 0.4 : 1,
                }}
              >
                <div style={{ fontWeight: isToday ? 800 : 600, fontSize: 12.5 }}>{d.getDate()}</div>
                {items.length > 0 && (
                  <div
                    className={overdue ? "pill pill-red" : "pill"}
                    style={{ fontSize: 10.5, marginTop: 3, padding: "1px 7px" }}
                  >
                    {items.length}
                  </div>
                )}
              </button>
            );
          })}
        </div>
      </Card>

      <Card title={fromIso(selected).toLocaleDateString("en-IN", { weekday: "long", day: "numeric", month: "long" })}>
        {dayList.length === 0 ? (
          <Empty icon="📅" title="Nothing scheduled" hint="Pick another day, or set a follow-up from a record." />
        ) : (
          <div className="table-wrap">
            <table className="data">
              <thead>
                <tr><th>{ui.leadNoun}</th><th>Stage</th><th>Score</th><th>Reschedule</th></tr>
              </thead>
              <tbody>
                {dayList.map((l) => (
                  <tr key={l.id}>
                    <td onClick={() => navigate(`/leads/${l.id}`)}>
                      <div style={{ fontWeight: 600 }}>{l.name}</div>
                      <div className="sub" style={{ fontSize: 12 }}>{l.phone ?? l.email ?? "—"}</div>
                    </td>
                    <td onClick={() => navigate(`/leads/${l.id}`)}>
                      <StagePill stageKey={l.stage_key ?? l.stage} stages={stages} />
                    </td>
                    <td onClick={() => navigate(`/leads/${l.id}`)}><ScoreChip score={l.score} /></td>
                    <td>
                      <div className="row">
                        <button className="btn btn-sm" onClick={(e) => { e.stopPropagation(); void reschedule(l, 1); }}>+1d</button>
                        <button className="btn btn-sm" onClick={(e) => { e.stopPropagation(); void reschedule(l, 3); }}>+3d</button>
                        <button className="btn btn-sm" onClick={(e) => { e.stopPropagation(); void reschedule(l, 7); }}>+1w</button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </Card>
      {toast.node}
    </div>
  );
}
