import { useEffect, useMemo, useState } from "react";
import { useApp, useLeads } from "../lib/store";
import { supabase } from "../lib/supabase";
import {
  Card, Empty, FieldInput, Modal, ScoreChip, Skeleton, StagePill,
  cellValue, humanize, useToast, LoadError, TruncationNotice } from "../components/ui";
import type { Lead } from "../lib/types";

// How many matches a server-side search returns. Deliberately larger than the
// command palette's 8 — this is the screen people come to when they want to
// work through a set, not jump to one record.
const SEARCH_LIMIT = 200;

// Columns are resolved at runtime: the industry registry proposes defaults and
// any custom field marked show_in_list is appended. Nothing is hardcoded,
// which is what lets one screen serve a hospital and a car dealership.

type SortKey = "created" | "score" | "name" | "follow_up";

export function Leads({ navigate }: { navigate: (to: string) => void }) {
  const { org, ui, stages, fields, profile } = useApp();
  const {
    leads, loading, error: leadsError, reload,
    // <TruncationNotice/> decides for itself from loaded vs total, so there is
    // no second copy of that comparison to fall out of sync.
    totalLeads, hasMore, loadMore, loadingMore,
  } = useLeads(org?.id);
  const [q, setQ] = useState("");
  const [stageFilter, setStageFilter] = useState("");
  const [tagFilter, setTagFilter] = useState("");
  const [sort, setSort] = useState<SortKey>("created");
  const [adding, setAdding] = useState(false);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const toast = useToast();

  // ── search ───────────────────────────────────────────────────────────────
  // This filtered `leads` in memory, which meant it searched the loaded page
  // and nothing else. Type a customer's name from eight months ago and the
  // screen answered "Nothing matches that filter" — not "not in what's
  // loaded", but a flat statement that the record does not exist. The command
  // palette had been querying the server correctly all along; this is the same
  // query, with the same debounce, on the screen where people expect to search.
  const [hits, setHits] = useState<Lead[] | null>(null);
  const [searching, setSearching] = useState(false);
  const [searchError, setSearchError] = useState<string | null>(null);
  // Retry needs something that CHANGES. The button was `setQ((s) => s)`, which
  // sets state to the identical value — React bails out of that render
  // entirely, the effect below never re-runs, and the only control on a failed
  // search did nothing at all when pressed. A counter is the state the user's
  // intent actually maps to: "ask again", not "change the term".
  const [retry, setRetry] = useState(0);
  const term = q.trim();
  const serverMode = term.length >= 2;

  useEffect(() => {
    if (!org || !serverMode) { setHits(null); setSearching(false); setSearchError(null); return; }
    setSearching(true);
    const t = setTimeout(async () => {
      // %,() are stripped because they are PostgREST filter syntax, not text —
      // an unescaped one turns a search into a malformed query. Same treatment
      // as CommandPalette.
      const safe = term.replace(/[%,()]/g, "");
      const { data, error } = await supabase
        .from("leads")
        .select("*")
        .eq("org_id", org.id)
        .or(`name.ilike.%${safe}%,email.ilike.%${safe}%,phone.ilike.%${safe}%`)
        .order("created_at", { ascending: false })
        .limit(SEARCH_LIMIT);
      if (error) {
        // Never fall back to the in-memory list on failure: that would render
        // a short result set as though the search had succeeded.
        setSearchError(error.message);
        setHits([]);
      } else {
        setSearchError(null);
        setHits((data as Lead[]) ?? []);
      }
      setSearching(false);
    }, 250);
    return () => clearTimeout(t);
  }, [term, serverMode, org, retry]);

  const columns = useMemo(() => {
    const extra = fields.filter((f) => f.show_in_list).map((f) => f.key);
    return Array.from(new Set([...ui.listColumns.filter((c) => c !== "stage" && c !== "score"), ...extra]));
  }, [ui.listColumns, fields]);

  const allTags = useMemo(() => {
    const s = new Set<string>();
    leads.forEach((l) => (Array.isArray(l.tags) ? l.tags : []).forEach((t) => s.add(t)));
    return Array.from(s).sort();
  }, [leads]);

  const filtered = useMemo(() => {
    // In server mode the text match already happened in Postgres, over every
    // record rather than the page. Stage, tag and sort still apply on top —
    // they operate on at most SEARCH_LIMIT rows, which is cheap and keeps the
    // controls behaving identically in both modes.
    const source = serverMode ? (hits ?? []) : leads;
    const needle = serverMode ? "" : q.trim().toLowerCase();
    const rows = source.filter((l) => {
      if (stageFilter && (l.stage_key ?? l.stage) !== stageFilter) return false;
      if (tagFilter && !(Array.isArray(l.tags) ? l.tags : []).includes(tagFilter)) return false;
      if (!needle) return true;
      return (
        l.name.toLowerCase().includes(needle) ||
        (l.email ?? "").toLowerCase().includes(needle) ||
        (l.phone ?? "").includes(needle)
      );
    });

    const sorted = [...rows];
    if (sort === "score") sorted.sort((a, b) => b.score - a.score);
    else if (sort === "name") sorted.sort((a, b) => a.name.localeCompare(b.name));
    else if (sort === "follow_up") {
      // Records with no follow-up sink to the bottom — an unscheduled record
      // isn't "due first", it's unplanned.
      sorted.sort((a, b) => {
        const av = a.next_follow_up_at ? new Date(a.next_follow_up_at).getTime() : Infinity;
        const bv = b.next_follow_up_at ? new Date(b.next_follow_up_at).getTime() : Infinity;
        return av - bv;
      });
    } else sorted.sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());
    return sorted;
  }, [leads, hits, serverMode, q, stageFilter, tagFilter, sort]);

  // Selecting rows then filtering them away would leave invisible records in
  // the selection — and a bulk action would hit records the user can't see.
  useEffect(() => {
    setSelected((prev) => {
      const visible = new Set(filtered.map((l) => l.id));
      const next = new Set(Array.from(prev).filter((id) => visible.has(id)));
      return next.size === prev.size ? prev : next;
    });
  }, [filtered]);

  const toggleRow = (id: string) => {
    setSelected((prev) => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });
  };

  const bulkUpdate = async (patch: Record<string, unknown>, label: string) => {
    const ids = Array.from(selected);
    if (!ids.length) return;
    // `.select("id")` so a refusal is distinguishable from success, and so the
    // count below comes from the server rather than from the selection. PostgREST
    // answers an UPDATE whose WHERE matches no VISIBLE row with 204 and
    // error: null, so "12 updated" was really "12 rows were selected" — a member
    // whose access was revoked keeps a usable token for up to an hour, and every
    // bulk action in that hour confirmed twelve changes and made none.
    const { data, error } = await supabase.from("leads").update(patch).in("id", ids).select("id");
    if (error) { toast.error(error.message); return; }
    const n = data?.length ?? 0;
    // Log against the records that actually changed, not against everything that
    // was ticked — an activity entry saying a record was moved is a claim about
    // that record, and the rows the server refused were never moved.
    const changed = (data ?? []).map((r) => r.id);
    if (org && changed.length) {
      const { error: actErr } = await supabase.from("activities").insert(
        changed.map((id) => ({
          org_id: org.id, lead_id: id, user_id: profile?.id ?? null,
          type: "system" as const, content: `${label} (bulk action).`,
        })),
      );
      if (actErr) console.warn("bulk action logged nowhere:", actErr.message);
    }
    setSelected(new Set());
    await reload();
    // The number comes from the server now. It used to come from the selection,
    // so a bulk action that changed nothing still reported the full count.
    if (n < ids.length) toast.error(`Only ${n} of ${ids.length} could be updated — you may no longer have permission.`);
    else toast.show(`${n} updated`);
  };

  if (loading) return <Skeleton kind="table" />;
  if (leadsError) return <LoadError message={leadsError} onRetry={() => void reload()} />;

  return (
    <div className="stack">
      {/* Search is unaffected by truncation now, so the notice says what is
          actually still limited: the list itself. It used to sit directly above
          a subtitle reading "2,000 total" — a banner saying there are more than
          2,000 records, and a count saying there are exactly 2,000. */}
      {!serverMode && (
        <TruncationNotice
          loaded={leads.length}
          total={totalLeads}
          noun={ui.leadNounPlural.toLowerCase()}
          what="Search covers all of them; this list is the most recent."
          onLoadMore={hasMore ? () => void loadMore() : undefined}
          loadingMore={loadingMore}
        />
      )}

      <div className="row">
        <div>
          <h1>{ui.leadNounPlural}</h1>
          <p className="sub" style={{ marginTop: 2 }}>
            {/* The denominator is the org's true total, from a count query —
                never the length of the slice that happens to be in memory. */}
            {serverMode
              ? `${filtered.length}${hits && hits.length >= SEARCH_LIMIT ? "+" : ""} matching “${term}”`
              : filtered.length === leads.length
                ? `${(totalLeads ?? leads.length).toLocaleString("en-IN")} total`
                : `${filtered.length.toLocaleString("en-IN")} of ${(totalLeads ?? leads.length).toLocaleString("en-IN")}`}
          </p>
        </div>
        <div className="spacer" />
        <button className="btn btn-primary" onClick={() => setAdding(true)}>+ {ui.addLabel}</button>
      </div>

      <div className="row row-wrap">
        <input
          className="input"
          style={{ maxWidth: 280 }}
          placeholder={`Search ${ui.leadNounPlural.toLowerCase()}…`}
          value={q}
          onChange={(e) => setQ(e.target.value)}
        />
        <select className="select" style={{ maxWidth: 180 }} value={stageFilter} onChange={(e) => setStageFilter(e.target.value)}>
          <option value="">All stages</option>
          {stages.map((s) => <option key={s.key} value={s.key}>{s.label}</option>)}
        </select>
        {allTags.length > 0 && (
          <select className="select" style={{ maxWidth: 160 }} value={tagFilter} onChange={(e) => setTagFilter(e.target.value)}>
            <option value="">All tags</option>
            {allTags.map((t) => <option key={t} value={t}>{t}</option>)}
          </select>
        )}
        <select className="select" style={{ maxWidth: 170 }} value={sort} onChange={(e) => setSort(e.target.value as SortKey)}>
          <option value="created">Newest first</option>
          <option value="score">Highest score</option>
          <option value="follow_up">Follow-up soonest</option>
          <option value="name">Name A–Z</option>
        </select>
        {(q || stageFilter || tagFilter) && (
          <button className="btn btn-sm btn-ghost" onClick={() => { setQ(""); setStageFilter(""); setTagFilter(""); }}>
            Clear
          </button>
        )}
        {serverMode && (
          <span className="sub" style={{ fontSize: 12 }}>
            {searching ? "Searching all records…" : "Searched all records"}
          </span>
        )}
      </div>

      {/* A failed search must not look like "no such customer". */}
      {searchError && <LoadError message={searchError} onRetry={() => setRetry((n) => n + 1)} />}

      {filtered.length === 0 ? (
        <Card>
          <Empty
            icon={ui.icon}
            title={
              searching ? "Searching…"
              : serverMode ? `No ${ui.leadNounPlural.toLowerCase()} match “${term}”`
              : leads.length === 0 ? `No ${ui.leadNounPlural.toLowerCase()} yet`
              : "Nothing matches that filter"
            }
            hint={
              searching ? undefined
              // The old copy here said "Try clearing the filters" for a record
              // that existed but sat outside the loaded page. It now searches
              // everything, so this statement is finally true.
              : serverMode ? `We searched every record in your workspace — name, email and phone. ${stageFilter || tagFilter ? "The stage and tag filters also apply; try clearing those." : "Check the spelling, or try part of a phone number."}`
              : leads.length === 0 ? "They'll appear here automatically once your widget or webhook is live."
              : "Try clearing the filters."
            }
          />
        </Card>
      ) : (
        <div className="table-wrap">
          <table className="data">
            <thead>
              <tr>
                <th style={{ width: 34 }}>
                  <input
                    type="checkbox"
                    aria-label="Select all"
                    checked={selected.size > 0 && selected.size === filtered.length}
                    ref={(el) => {
                      // Partial selection gets the indeterminate dash rather
                      // than an unchecked box, which would imply "none".
                      if (el) el.indeterminate = selected.size > 0 && selected.size < filtered.length;
                    }}
                    onChange={(e) =>
                      setSelected(e.target.checked ? new Set(filtered.map((l) => l.id)) : new Set())
                    }
                  />
                </th>
                {columns.map((c) => <th key={c}>{humanize(c)}</th>)}
                <th>Stage</th>
                <th>Score</th>
              </tr>
            </thead>
            <tbody>
              {filtered.map((l) => (
                <tr
                  key={l.id}
                  className={selected.has(l.id) ? "selected" : undefined}
                  onClick={() => navigate(`/leads/${l.id}`)}
                >
                  <td onClick={(e) => e.stopPropagation()}>
                    <input
                      type="checkbox"
                      aria-label={`Select ${l.name}`}
                      checked={selected.has(l.id)}
                      onChange={() => toggleRow(l.id)}
                    />
                  </td>
                  {columns.map((c) => (
                    <td key={c} style={c === "name" ? { fontWeight: 600 } : undefined}>
                      {c === "name" ? (
                        <div>
                          <div>{l.name}</div>
                          {Array.isArray(l.tags) && l.tags.length > 0 && (
                            <div className="row-wrap" style={{ gap: 4, marginTop: 3 }}>
                              {l.tags.slice(0, 3).map((t) => (
                                <span key={t} className="pill pill-muted" style={{ fontSize: 10.5, padding: "1px 7px" }}>{t}</span>
                              ))}
                            </div>
                          )}
                        </div>
                      ) : cellValue(l, c)}
                    </td>
                  ))}
                  <td><StagePill stageKey={l.stage_key ?? l.stage} stages={stages} /></td>
                  <td><ScoreChip score={l.score} /></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* Range-based pagination. Before this there was no offset, no cursor and
          no "load more" anywhere in the app, so a Business customer who bought
          50,000 records had no route to record 2,001 through the UI at all. */}
      {!serverMode && hasMore && (
        <div className="row" style={{ justifyContent: "center", paddingBottom: 6 }}>
          <button className={`btn${loadingMore ? " btn-busy" : ""}`} onClick={() => void loadMore()} disabled={loadingMore}>
            {loadingMore
              ? "Loading…"
              : `Load more — ${((totalLeads ?? 0) - leads.length).toLocaleString("en-IN")} older ${ui.leadNounPlural.toLowerCase()} remaining`}
          </button>
        </div>
      )}
      {serverMode && hits && hits.length >= SEARCH_LIMIT && (
        <p className="sub" style={{ textAlign: "center", fontSize: 12.5 }}>
          Showing the first {SEARCH_LIMIT} matches. Add more of the name, email or number to narrow it.
        </p>
      )}

      {selected.size > 0 && (
        <div className="bulkbar">
          <b>{selected.size} selected</b>
          <select
            className="select"
            style={{ maxWidth: 150, background: "transparent", borderColor: "rgba(255,255,255,.2)" }}
            defaultValue=""
            onChange={(e) => {
              if (!e.target.value) return;
              const label = stages.find((s) => s.key === e.target.value)?.label ?? e.target.value;
              void bulkUpdate({ stage_key: e.target.value, updated_at: new Date().toISOString() }, `Moved to ${label}`);
              e.target.value = "";
            }}
          >
            <option value="">Move to…</option>
            {stages.map((s) => <option key={s.key} value={s.key}>{s.label}</option>)}
          </select>
          <button
            className="btn btn-sm"
            onClick={() => void bulkUpdate({ assigned_to: profile?.id ?? null }, "Assigned")}
          >
            Assign to me
          </button>
          <button
            className="btn btn-sm"
            onClick={() => {
              const at = new Date(); at.setDate(at.getDate() + 1);
              void bulkUpdate({ next_follow_up_at: at.toISOString() }, "Follow-up set for tomorrow");
            }}
          >
            Follow up tomorrow
          </button>
          <button className="btn btn-sm btn-ghost" style={{ color: "inherit" }} onClick={() => setSelected(new Set())}>
            Clear
          </button>
        </div>
      )}

      {adding && (
        <AddLead
          onClose={() => setAdding(false)}
          onSaved={async () => { setAdding(false); await reload(); toast.show(`${ui.leadNoun} added`); }}
          orgId={org!.id}
          userId={profile?.id ?? null}
        />
      )}
      {toast.node}
    </div>
  );
}

function AddLead({ orgId, userId, onClose, onSaved }: {
  orgId: string; userId: string | null; onClose: () => void; onSaved: () => void;
}) {
  const { ui, fields, stages } = useApp();
  const [name, setName] = useState("");
  const [phone, setPhone] = useState("");
  const [email, setEmail] = useState("");
  const [custom, setCustom] = useState<Record<string, unknown>>({});
  const [saving, setSaving] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [dupe, setDupe] = useState<Lead | null>(null);
  // Why the duplicate lookup failed, when it does. The absence of the warning
  // below reads as "this person is not in your CRM", and off a failed read that
  // is a claim we have no basis for.
  const [dupeError, setDupeError] = useState<string | null>(null);

  const first = stages[0]?.key ?? "new";

  // Duplicate check as you type. Finding out you created a second record for
  // someone after the fact is the most common way CRM data rots.
  useEffect(() => {
    const term = email.trim().toLowerCase() || phone.trim();
    if (term.length < 5) { setDupe(null); setDupeError(null); return; }
    const t = setTimeout(async () => {
      let query = supabase.from("leads").select("id, name, email, phone, stage_key, stage, score").eq("org_id", orgId);
      query = email.trim() ? query.eq("email", email.trim().toLowerCase()) : query.eq("phone", phone.trim());
      // The error was discarded, so a failed lookup looked exactly like "no
      // match" — the warning below simply never appeared and the second record
      // got created with nothing on screen to stop it.
      const { data, error } = await query.limit(1);
      if (error) { setDupe(null); setDupeError(error.message); return; }
      setDupeError(null);
      setDupe((data?.[0] as Lead) ?? null);
    }, 400);
    return () => clearTimeout(t);
  }, [email, phone, orgId]);

  const save = async () => {
    if (!name.trim()) { setErr("Name is required"); return; }
    if (!phone.trim() && !email.trim()) { setErr("Add a phone number or an email — one of the two is needed to follow up"); return; }
    setSaving(true);
    setErr(null);

    const { data, error } = await supabase.from("leads").insert({
      org_id: orgId,
      name: name.trim(),
      phone: phone.trim() || null,
      email: email.trim().toLowerCase() || null,
      source: "manual",
      stage_key: first,
      custom,
      assigned_to: userId,
      next_follow_up_at: new Date(Date.now() + 24 * 3600 * 1000).toISOString(),
    }).select("id").single();

    setSaving(false);
    if (error) { setErr(error.message); return; }

    if (data?.id) {
      // Secondary to the record that has already been created, so a failure
      // here must not fail the save — but it must not be invisible either. An
      // unread error meant the Activity feed quietly stopped matching what
      // happened, and a record with no "added" entry reads as one that arrived
      // by some route nobody can account for.
      const { error: actErr } = await supabase.from("activities").insert({
        org_id: orgId, lead_id: data.id, user_id: userId,
        type: "system", content: `${ui.leadNoun} added manually.`,
      });
      if (actErr) console.warn("lead creation logged nowhere:", actErr.message);
    }
    onSaved();
  };

  return (
    <Modal title={ui.addLabel} onClose={onClose}>
      <div className="field">
        <label className="label">Name *</label>
        <input className="input" value={name} onChange={(e) => setName(e.target.value)} autoFocus />
      </div>
      <div className="row" style={{ gap: 10 }}>
        <div className="field" style={{ flex: 1 }}>
          <label className="label">Phone</label>
          <input className="input" value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="+91…" />
        </div>
        <div className="field" style={{ flex: 1 }}>
          <label className="label">Email</label>
          <input className="input" type="email" value={email} onChange={(e) => setEmail(e.target.value)} />
        </div>
      </div>

      {/* Said out loud rather than left blank: a missing warning is read as "not
          a duplicate", which is the one thing a failed check cannot tell us. */}
      {!dupe && dupeError && (
        <div
          className="card"
          style={{ background: "var(--bg)", marginBottom: 14, padding: 12 }}
        >
          <div style={{ fontWeight: 700, fontSize: 13 }}>Couldn't check for duplicates</div>
          <div className="sub" style={{ fontSize: 12.5, marginTop: 3 }}>
            {dupeError} — this record may already exist. Search for it before saving.
          </div>
        </div>
      )}

      {dupe && (
        <div
          className="card"
          style={{ background: "var(--amber-soft)", borderColor: "var(--amber)", marginBottom: 14, padding: 12 }}
        >
          <div style={{ fontWeight: 700, fontSize: 13 }}>⚠️ Already in your CRM</div>
          <div className="sub" style={{ fontSize: 12.5, marginTop: 3 }}>
            <b>{dupe.name}</b> has the same {email.trim() ? "email" : "phone"}. Saving will create a second record.
          </div>
        </div>
      )}

      {fields.slice(0, 6).map((f) => (
        <div className="field" key={f.id}>
          {f.type !== "checkbox" && <label className="label">{f.label}</label>}
          <FieldInput def={f} value={custom[f.key]} onChange={(v) => setCustom({ ...custom, [f.key]: v })} />
        </div>
      ))}

      {err && <p style={{ color: "var(--red)", fontSize: 13 }}>{err}</p>}

      <div className="row" style={{ justifyContent: "flex-end", marginTop: 12 }}>
        <button className="btn" onClick={onClose}>Cancel</button>
        <button className="btn btn-primary" onClick={save} disabled={saving}>
          {saving ? "Saving…" : dupe ? "Save anyway" : "Save"}
        </button>
      </div>
    </Modal>
  );
}
